package dominoes

// Domino is a pair of values, one for each half of a stone.
type Domino [2]int

// MakeChain takes a set of dominoes and attempts to order them into a
// correct domino chain: the dots on one half of a stone match the dots on
// the neighboring half of an adjacent stone, and the dots on the two halves
// which don't have a neighbor (the first and last stone) match each other.
//
// It returns the chain and true on success, or nil and false if no valid
// chain can be formed from the given dominoes.
func MakeChain(input []Domino) ([]Domino, bool) {
	if len(input) == 0 {
		return []Domino{}, true
	}
	if len(input) == 1 {
		if input[0][0] == input[0][1] {
			return []Domino{input[0]}, true
		}
		return nil, false
	}

	used := make([]bool, len(input))
	chain := make([]Domino, 0, len(input))

	// search extends the chain with one unused domino at a time, trying both
	// orientations, and succeeds when all dominoes are placed and the
	// exposed ends of the chain match.
	var search func() bool
	search = func() bool {
		if len(chain) == len(input) {
			return chain[0][0] == chain[len(chain)-1][1]
		}
		tip := chain[len(chain)-1][1]
		for i := range input {
			if used[i] {
				continue
			}
			d := input[i]
			if d[0] == tip {
				used[i] = true
				chain = append(chain, d)
				if search() {
					return true
				}
				chain = chain[:len(chain)-1]
				used[i] = false
			}
			if d[1] != d[0] && d[1] == tip {
				used[i] = true
				chain = append(chain, Domino{d[1], d[0]})
				if search() {
					return true
				}
				chain = chain[:len(chain)-1]
				used[i] = false
			}
		}
		return false
	}

	// The chain is a cycle, so any domino in it can serve as the first one;
	// fixing the first domino (in both orientations) breaks the rotational
	// symmetry without losing any solution.
	for _, first := range [2]Domino{input[0], {input[0][1], input[0][0]}} {
		used[0] = true
		chain = append(chain, first)
		if search() {
			return chain, true
		}
		chain = chain[:len(chain)-1]
		used[0] = false
	}
	return nil, false
}
